<div class="admin-record-columns"><section class="registration-admin-group"><h3>Contato</h3><dl class="inbox-fields"><?php foreach(['cpf'=>'CPF','phone'=>'WhatsApp','email'=>'E-mail','instagram'=>'Instagram','city_state'=>'Cidade/UF','city'=>'Cidade'] as $key=>$label):$value=$payload[$key]??'';if($value===''||$value===[])continue;?><div><dt><?=h($label)?></dt><dd><?=h(registration_value_label($fields[$key]??[],$value))?></dd></div><?php endforeach;?></dl></section><section class="registration-admin-group"><h3>Disponibilidade</h3><?php $shown=false;foreach(['availability','preferred_days','preferred_time'] as $key):$value=$payload[$key]??'';if($value===''||$value===[])continue;$shown=true;?><p><strong><?=h((string)($fields[$key]['label']??$key))?>:</strong> <?=h(registration_value_label($fields[$key]??[],$value))?></p><?php endforeach;?><?php if(!$shown):?><p class="muted">Nenhuma disponibilidade registrada.</p><?php endif;?></section></div>
